function useTerminalLocale(locale: Locale, onLocaleChange: (locale: Locale) => void) {
  useEffect(() => {
    const baseDictionary = { ...englishUi, ...extraEnglishUi, ...correlationEnglishUi, ...gridEnglishUi };
    const dictionary = locale === "en" ? baseDictionary : Object.fromEntries(Object.entries(baseDictionary).map(([tr, en]) => [en, tr]));
    const translate = (value: string) => Object.entries(dictionary).sort(([left], [right]) => right.length - left.length).reduce((result, [from, to]) => result.replaceAll(from, to), value);
    const translateElement = (root: Node) => {
      if (root.nodeType === Node.TEXT_NODE) { const next = translate(root.nodeValue ?? ""); if (next !== root.nodeValue) root.nodeValue = next; return; }
      const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
      const nodes: Text[] = []; let node: Node | null;
      while ((node = walker.nextNode())) nodes.push(node as Text);
      nodes.forEach((text) => { const next = translate(text.nodeValue ?? ""); if (next !== text.nodeValue) text.nodeValue = next; });
      const fields = root instanceof HTMLInputElement || root instanceof HTMLTextAreaElement ? [root] : root instanceof HTMLElement ? Array.from(root.querySelectorAll<HTMLInputElement | HTMLTextAreaElement>("input[placeholder], textarea[placeholder]")) : [];
      fields.forEach((field) => { if (field.placeholder && dictionary[field.placeholder]) field.placeholder = dictionary[field.placeholder]; if (field.value && dictionary[field.value]) { field.value = dictionary[field.value]; field.dispatchEvent(new Event("input", { bubbles: true })); } });
    };
    document.documentElement.lang = locale === "en" ? "en" : "tr";
    translateElement(document.body);
    let toggle = document.getElementById("terminal-locale-toggle");
    if (!toggle) {
      toggle = document.createElement("div"); toggle.id = "terminal-locale-toggle"; toggle.className = "locale-switcher"; toggle.setAttribute("aria-label", "Language selector");
      const tr = document.createElement("button"); tr.textContent = "TR"; tr.type = "button"; tr.addEventListener("click", () => onLocaleChange("tr"));
      const en = document.createElement("button"); en.textContent = "EN"; en.type = "button"; en.addEventListener("click", () => onLocaleChange("en"));
      toggle.append(tr, en); document.body.append(toggle);
    }
    toggle.querySelectorAll("button").forEach((button) => button.classList.toggle("active", button.textContent?.toLowerCase() === locale));
    const observer = new MutationObserver((entries) => entries.forEach((entry) => { if (entry.type === "characterData") translateElement(entry.target); entry.addedNodes.forEach((node) => translateElement(node)); }));
    observer.observe(document.body, { childList: true, characterData: true, subtree: true });
    return () => observer.disconnect();
  }, [locale, onLocaleChange]);
}

